from gurobipy import Model, GRB, quicksum

def build_and_solve():
    warehouses = []
    warehouse_capacities = {}
    products = []
    product_values = {}
    product_weights = {}
    for rec in LEGACY_RECORDS:
        src = rec['source']
        vals = rec['values']
        if src.endswith('capacity.csv'):
            w = vals['Warehouse ID']
            warehouses.append(w)
            warehouse_capacities[w] = float(vals['Capacity'])
        elif src.endswith('products.csv'):
            p = vals['ProductName']
            products.append(p)
            product_values[p] = float(vals['Value'])
            product_weights[p] = float(vals['Weight'])
    if len(warehouses) == 0 or len(products) == 0:
        raise RuntimeError('Missing warehouse or product data.')
    for w in warehouses:
        if w not in warehouse_capacities:
            raise RuntimeError(f'Missing capacity for warehouse {w}')
    for p in products:
        if p not in product_values or p not in product_weights:
            raise RuntimeError(f'Missing value/weight for product {p}')
    m = Model()
    m.Params.MIPGap = 0.0001
    x_vars = m.addVars(warehouses, products, vtype=GRB.INTEGER, lb=0, name='')
    m.setObjective(quicksum((product_values[p] * x_vars[w, p] for w in warehouses for p in products)), GRB.MAXIMIZE)
    for w in warehouses:
        m.addConstr(quicksum((product_weights[p] * x_vars[w, p] for p in products)) <= warehouse_capacities[w], name='cap_' + w.replace(' ', '_'))
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(f'ObjVal {m.ObjVal}')
        for w in warehouses:
            for p in products:
                v = x_vars[w, p]
                print(f'{v.VarName} {v.X}')
    else:
        print(f'Solver status: {m.Status}')
    return m
m = build_and_solve()